import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Plugin development overview","description":"","frontmatter":{"title":"Plugin development overview","docId":"developer.plugins.index","translationKey":"developer.plugins.index","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","translationRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","order":240},"headers":[],"relativePath":"en/developer/plugins/index.md","filePath":"en/developer/plugins/index.md","lastUpdated":1795727787000}`),a={name:`en/developer/plugins/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="plugin-development-overview" tabindex="-1">Plugin development overview <a class="header-anchor" href="#plugin-development-overview" aria-label="Permalink to “Plugin development overview”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Choose the smallest plugin boundary that provides your integration. TikTools discovers runtime packages from built-in, user and development roots; adding a package does not require recompiling a named plugin into the host. Use the matching devkit/SDK and a private development profile before testing effects.</p><h2 id="follow-the-authoring-path" tabindex="-1">Follow the authoring path <a class="header-anchor" href="#follow-the-authoring-path" aria-label="Permalink to “Follow the authoring path”">​</a></h2><ol><li>Start with <a href="./quickstart.html">quickstart</a> to scaffold, validate and build an isolated package.</li><li>Choose a <a href="./runtimes.html">runtime</a> based on native dependencies and trust, not file extension alone.</li><li>Declare <a href="./permissions-ui.html">permissions and UI</a> so the host can review effects and render configuration.</li><li>Use <a href="./packaging-registry.html">packaging and registry</a> for integrity, publisher trust and update policy.</li></ol><p>The low-level Rust authority is <code>crates/tiktools-plugin-api</code>: manifest validation, protocol and UI contracts. <code>crates/tiktools-plugin-sdk</code> offers the Rust author surface; <code>packages/plugin-sdk</code> contains TypeScript helpers and the <a href="https://github.com/nglmercer/TikTools-app/blob/remake/packages/plugin-sdk/plugin.schema.json" target="_blank" rel="noreferrer">editor schema</a>. Runtime loading belongs to <code>crates/tiktools-plugin-loader</code>, not the frontend.</p><h2 id="understand-contributions" tabindex="-1">Understand contributions <a class="header-anchor" href="#understand-contributions" aria-label="Permalink to “Understand contributions”">​</a></h2><p>An action requests a side effect through a typed result. Event sources publish triggers; observers receive stable <code>{topic,data}</code> domain envelopes with bounded delivery. Processors add side-effect-free evidence under <code>event.intel</code>, with deadlines, deterministic merging and health isolation. Declarative settings/actions let the host render ordinary configuration. A custom compiled page uses a restricted plugin broker in its own frame/window; its script never becomes part of the main Vue runtime.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>These are focused host/SDK checks, not validation of an arbitrary external package.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Native, process, declarative and QuickJS-backed <code>napi-vm</code> paths are implemented. WASM is an optional runtime slot without an active general-purpose engine in normal builds. Example integrations live in the separate <a href="https://github.com/nglmercer/plugins-example-tiktools" target="_blank" rel="noreferrer">plugins-example-tiktools repository</a>; source names in old documents do not make them bundled product features.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>For discovery failure, inspect manifest compatibility, root precedence, target and entry path. For a denied intent, inspect declared and granted capabilities instead of bypassing the host. An uncertain startup must be reconciled before replacement. Native/process boundaries retain OS-level trust limits; the runtime name alone never establishes a sandbox.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};